INSERT INTO `ContentBlock` (`id`, `page`, `type`, `sortOrder`, `data`, `updatedAt`) VALUES
('content-home-slider', 'HOME', 'SLIDER', 0, '{"slides":[{"kicker":"Government resolutions","title":"Every GR a Talati needs, in one place.","subtext":"Resolutions and circulars from the Revenue and Panchayat departments, sorted by subject and date, each linked to its official source.","ctaLabel":"Browse GRs & circulars","category":"GR_CIRCULARS"},{"kicker":"Land records","title":"7/12, 8-A and varsai — the procedure, step by step.","subtext":"Procedure notes and forms for the land record work handled at the village office, updated whenever the rules change.","ctaLabel":"Open land record guides","category":"LAND_RECORDS"},{"kicker":"Exam preparation","title":"Preparing for the Talati-cum-Mantri exam?","subtext":"The full syllabus, subject notes and seven years of previous papers with answer keys — free to download.","ctaLabel":"Get study material","category":"EXAM_PREPARATION"}]}', CURRENT_TIMESTAMP(3));

-- Seed 10 Article rows (spec Appendix A)
INSERT INTO `Article` (`id`, `category`, `title`, `excerpt`, `body`, `publishedAt`, `updatedAt`) VALUES
('article-seed-01', 'LAND_RECORDS', 'Revised procedure for varsai (succession) entries in village form 6', 'The Revenue Department has updated the documents required for heirship entries and the notice period before certification.', 'The Revenue Department has issued revised instructions for recording varsai, or succession, entries in village form 6. Applicants must now submit the death certificate, a list of legal heirs attested by the Gram Panchayat, and an affidavit confirming no dispute exists among the heirs.\n\nThe notice period before an entry is certified has been extended from 15 to 30 days, giving other claimants more time to raise an objection at the Mamlatdar office. Talatis should record the date the notice is posted on the village notice board, since that date now starts the clock.\n\nOffices that already have pending varsai applications should apply the new notice period going forward rather than restart cases already past their original notice date.', '2026-10-15 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-02', 'SALARY_SERVICE_RULES', 'GR: Dearness allowance revised for panchayat service employees', 'The Finance Department resolution extends the revised DA rate to Talati-cum-Mantri and other panchayat cadres.', 'The Finance Department has issued a government resolution extending the revised dearness allowance rate to Talati-cum-Mantri and other panchayat service cadres, bringing them in line with the rate already applicable to state government employees.\n\nThe revised rate takes effect from the pay drawn for the current month, with arrears for the preceding two months payable in the next salary cycle. Offices should update their pay bill software before processing the salary for this month.\n\nA full rate table by pay matrix level is attached to the original resolution on the Finance Department website; this summary covers only the headline change.', '2026-10-12 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-03', 'PANCHAYAT_ADMINISTRATION', 'Circular on Gram Sabha scheduling for the coming quarter', 'Dates, minimum quorum and the agenda items that must be recorded in the Gram Sabha register.', 'The circular sets out the dates for the coming quarter Gram Sabha meetings and restates the minimum quorum required for a meeting to proceed. At least one-tenth of the electors on the village voter list, or 100 electors, whichever is less, must be present.\n\nEvery Gram Sabha must record attendance, the agenda items discussed, and any resolutions passed in the Gram Sabha register, with the Sarpanch and Talati-cum-Mantri both signing the minutes on the same day.\n\nOffices that could not hold a meeting in the previous quarter due to lack of quorum must note the failed attempt in the register before scheduling a fresh date.', '2026-10-09 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-04', 'EXAM_PREPARATION', 'Talati-cum-Mantri exam: complete syllabus and marking scheme', 'Subject-wise syllabus with weightage, negative marking rules and a reading list for each section.', 'This note lays out the subject-wise syllabus for the Talati-cum-Mantri recruitment exam along with the weightage given to each section: general knowledge, Gujarati and English language, quantitative aptitude, and panchayat administration.\n\nThe exam carries negative marking of one-quarter mark for every wrong answer, so candidates are advised to attempt a question only when reasonably confident. A short reading list is included for the panchayat administration section, which tends to carry the most scoring questions relative to its difficulty.\n\nCandidates preparing from older material should check this syllabus against it first, since the weightage for a few sections changed in the most recent recruitment cycle.', '2026-10-06 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-05', 'LAND_RECORDS', 'How to issue a 7/12 and 8-A extract through the e-Dhara system', 'Step-by-step note on generating, signing and recording digitally issued land record extracts.', 'This note walks through generating a 7/12 or 8-A extract through the e-Dhara system, from logging in at the taluka e-Dhara kendra to the final digitally signed printout.\n\nThe applicant request is entered against the survey number, the system pulls the current record from the land record database, and the Talati or an authorised operator verifies the entries before the extract is digitally signed and recorded in the issue register.\n\nAny mismatch between the e-Dhara record and the physical village record should be flagged to the Mamlatdar office before the extract is issued, not corrected informally at the counter.', '2026-10-02 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-06', 'PANCHAYAT_ADMINISTRATION', 'House tax assessment register: updated format and rates', 'The revised register format for property tax assessment in gram panchayats, with a worked example.', 'The revised register format for property tax assessment adds separate columns for the built-up area, the usage category (residential, commercial, or mixed), and the applicable rate per square foot, replacing the single combined column in the older format.\n\nA worked example is included showing how to calculate the annual assessment for a mixed-use property with both a residential first floor and a shop on the ground floor.\n\nGram panchayats already using the older register should migrate existing entries to the new format at the start of the next assessment year rather than mid-year.', '2026-09-28 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-07', 'SALARY_SERVICE_RULES', 'Leave rules for panchayat employees — a plain-language summary', 'Earned, half-pay, commuted and casual leave explained with the forms needed for each.', 'This summary sets out the four main leave categories available to panchayat employees: earned leave, half-pay leave, commuted leave, and casual leave, along with the accrual rate and maximum accumulation for each.\n\nCasual leave is sanctioned by the Taluka Development Officer and does not require a medical certificate; half-pay and commuted leave both require supporting documentation and are recorded separately in the service book.\n\nThe form required for each leave type is listed at the end of this note, along with the minimum notice period expected before the leave begins, where one applies.', '2026-09-24 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-08', 'FORMS_DOWNLOADS', 'Birth and death registration: forms and timelines', 'All forms for registration at the gram panchayat level, including delayed registration.', 'This note lists every form required for birth and death registration at the gram panchayat level, including the forms used when a registration is filed after the standard 21-day window.\n\nA delayed registration beyond 30 days requires an additional affidavit and, beyond one year, an order from the area executive magistrate before the Talati can register the event.\n\nAll forms are available for download at the end of this note; offices are advised to keep a stock of the standard, non-delayed forms printed and ready at the counter.', '2026-09-19 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-09', 'EXAM_PREPARATION', 'Previous year question papers with answer keys (2019–2025)', 'Seven years of Talati recruitment papers with official answer keys and short explanations.', 'This collection gathers seven years of Talati-cum-Mantri recruitment question papers, from 2019 through 2025, each paired with the official answer key released by the recruitment board.\n\nA short explanation is included for questions that were later withdrawn or revised by the board, so candidates studying from these papers know which answers to treat with caution.\n\nQuestions are not re-sorted by topic in this collection; candidates wanting a topic-wise breakdown should refer to the separate subject notes published alongside the syllabus.', '2026-09-15 09:00:00', CURRENT_TIMESTAMP(3)),
('article-seed-10', 'GR_CIRCULARS', 'GR index: all Revenue Department resolutions for 2026', 'A dated index of the resolutions issued this year, with links to each original document.', 'This index lists every Revenue Department resolution issued so far in 2026, in date order, with a short description and a link to the original scanned document for each entry.\n\nResolutions are grouped by the broad subject they cover: land records, panchayat finance, service rules, and general administration, so a reader can scan just the section relevant to their work.\n\nThe index is updated as new resolutions are issued through the year; this version reflects everything published up to the date shown above.', '2026-09-10 09:00:00', CURRENT_TIMESTAMP(3));
